import { Module } from '@nestjs/common';
import { OrdersModule } from './modules/orders/orders.module';
import { StockModule } from './modules/stock/stock.module';

@Module({ imports: [OrdersModule, StockModule] })
export class AppModule {}

import { Module } from '@nestjs/common';
import { StockService } from './stock.service';
import { StockSyncService } from './stock-sync.service';

@Module({ providers: [StockService, StockSyncService], exports: [StockService] })
export class StockModule {}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../prisma.service';

@Injectable()
export class StockService {
  constructor(private readonly db: PrismaService) {}

  async available(variantId: string): Promise<number> {
    const v = await this.db.variant.findUniqueOrThrow({ where: { id: variantId } });
    return v.onHand - v.reserved;
  }

  async release(variantId: string, qty: number) {
    return this.db.variant.update({ where: { id: variantId }, data: { reserved: { decrement: qty } } });
  }
}

import { Injectable, OnEvent } from '@nestjs/common';
import { StockService } from './stock.service';

@Injectable()
export class StockSyncService {
  constructor(private readonly stock: StockService) {}

  /** Give reserved stock back when an order is cancelled. */
  @OnEvent('order.cancelled')
  async reconcile(order: { lines: { variantId: string; qty: number }[] }) {
    for (const l of order.lines) await this.stock.release(l.variantId, l.qty);
  }
}

import { Module } from '@nestjs/common';
import { OrdersController } from './orders.controller';
import { OrdersService } from './orders.service';

@Module({ controllers: [OrdersController], providers: [OrdersService] })
export class OrdersModule {}

import { Injectable } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';

@Injectable()
export class OrdersService {
  constructor(private readonly events: EventEmitter2) {}

  async cancel(id: string) {
    const order = { id, lines: [] as { variantId: string; qty: number }[] };
    this.events.emit('order.cancelled', order);
    return order;
  }
}

import { Controller, Param, Post } from '@nestjs/common';
import { OrdersService } from './orders.service';

@Controller('orders')
export class OrdersController {
  constructor(private readonly orders: OrdersService) {}

  @Post(':id/cancel')
  cancel(@Param('id') id: string) {
    return this.orders.cancel(id);
  }
}

